{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Seek a materially higher general cap"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "a tipping basket (recovery from dollar one once crossed), and sensible per-claim aggregation rules."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Eighteen months is short for general claims; seek a longer period"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Capacity and title should not share the general cap or 18-month time bar"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "fraud and deliberate concealment should not be protected by contractual limitations."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "exclude general data-room/public-register disclosure as a blanket qualification."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Limit any Buyer-knowledge bar to actual knowledge of specifically identified Buyer deal principals, not advisers, constructive knowledge or matters merely discoverable from records."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require the executed consent, evidence that all conditions are met or waived, and no adverse conditions, before Completion."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require a completion payoff letter, repayment from Completion funds, and an effective release/discharge as a condition to Completion."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Require the bonuses, payroll tax, superannuation and other employer costs to be quantified and either paid by the Seller before Completion or deducted/treated as debt-like"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Require cleared payment and executed assignment/confirmatory transfer before Completion, or a holdback and specific indemnity covering the amount, delay, failure to transfer, and resulting loss."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Obtain an updated DD-006 investigation and negotiate incident-specific protection."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Do not accept the Seller’s characterisation alone. Obtain the contracts, renewal dates and termination rights"
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "preserve claims under specific indemnities and express completion obligations, and carve out fraud and deliberate concealment."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012 is evidence of what the share register records, not a substitute for contractual title protection or Buyer verification."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Seek a separate tax indemnity and robust IP ownership, assignment and infringement warranties, with appropriate survival and caps."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": true
}

